+//go:build linux
+
+// Copyright 2026 The Stargate Authors
+// SPDX-License-Identifier: Apache-2.0
+
+package integration
+
+import "testing"
+
+// t034OtherwiseCleanResult makes every existing vacuity guard pass so each
+// integrity regression asks one thing: can an unreliable capture still earn
+// a clean zero-leak verdict?
+func t034OtherwiseCleanResult() t034Result {
+	ifaces := []string{"lo", "eth0"}
+	controls := map[string][]string{
+		"t206-control-pre.onion":  ifaces,
+		"t206-control-post.onion": ifaces,
+	}
+	var records []t034Record
+	for name := range controls {
+		for _, iface := range ifaces {
+			records = append(records, t034Record{Iface: iface, Name: name})
+		}
+	}
+	return t034Result{
+		ifaces:             ifaces,
+		started:            int32(len(ifaces)),
+		captureHealth:      map[string]t034CaptureHealth{"lo": {statsKnown: true, packets: 4}, "eth0": {statsKnown: true, packets: 4}},
+		controls:           controls,
+		records:            records,
+		issued:             1,
+		completed:          1,
+		wantPartitions:     1,
+		upstreamPartitions: 1,
+	}
+}
+
+func TestT206CaptureReadErrorRejectsOtherwiseCleanVerdict(t *testing.T) {
+	res := t034OtherwiseCleanResult()
+	if err := t034Verdict(res); err != nil {
+		t.Fatalf("test fixture must satisfy controls, routed forwarding, and partition guards before fault injection: %v", err)
+	}
+	for _, iface := range res.ifaces {
+		health := res.captureHealth[iface]
+		health.readErrors = []string{"injected non-timeout packet read error"}
+		res.captureHealth[iface] = health
+	}
+	if err := t034Verdict(res); err == nil {
+		t.Fatal("zero-leak verdict accepted a recovered non-timeout capture read error despite successful before/after controls and routed forwarding")
+	}
+}
+
+func TestT206PacketDropRejectsOtherwiseCleanVerdict(t *testing.T) {
+	res := t034OtherwiseCleanResult()
+	if err := t034Verdict(res); err != nil {
+		t.Fatalf("test fixture must satisfy controls, routed forwarding, and partition guards before fault injection: %v", err)
+	}
+	health := res.captureHealth["eth0"]
+	health.drops = 1
+	res.captureHealth["eth0"] = health
+	if err := t034Verdict(res); err == nil {
+		t.Fatal("zero-leak verdict accepted a nonzero packet-socket drop count despite successful before/after controls and routed forwarding")
+	}
+}
